import { useEffect, useRef, useState } from 'react';

// HEY Research Lab project intelligence, from https://heyresearch.xyz/developers/embeds
export function HeyProject() {
  const frame = useRef(null);
  const [height, setHeight] = useState(196);

  useEffect(() => {
    const onMessage = (event) => {
      if (!frame.current || event.source !== frame.current.contentWindow) return;
      const data = event.data;
      if (data && data.type === 'hey-embed:height' && typeof data.height === 'number') {
        setHeight(Math.min(Math.max(Math.ceil(data.height), 60), 1200));
      }
    };
    window.addEventListener('message', onMessage);
    return () => window.removeEventListener('message', onMessage);
  }, []);

  return (
    <iframe
      ref={frame}
      src={"https://heyresearch.xyz/embed/project/agentos?variant=builder&theme=auto"}
      title={"AgentOS on HEY Research Lab"}
      height={height}
      loading="lazy"
      sandbox="allow-scripts allow-popups allow-popups-to-escape-sandbox"
      style={{ border: 0, width: '100%', display: 'block' }}
    />
  );
}

